with recursive customer_tree as (select customer_id, parent_customer_id, customer_name, 1 level_num from cap_customer where parent_customer_id is null union all select c.customer_id, c.parent_customer_id, c.customer_name, ct.level_num + 1 level_num from cap_customer c join customer_tree ct on c.parent_customer_id = ct.customer_id where ct.level_num < 5) select customer_id, parent_customer_id, customer_name, level_num from customer_tree order by level_num, customer_id;
